{
  "artifact": {
    "path": "union-acceptance/readable-paths/unrestricted-compatibility.test.mjs",
    "text": "import { test } from 'node:test';
import assert from 'node:assert';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createAgentTools } from '../../src/agent-tools.mjs';

test('unrestricted-compatibility', () => {
  const root = mkdtempSync(join(tmpdir(), 'unrestricted-'));
  try {
    writeFileSync(join(root, 'public.txt'), 'public content');
    writeFileSync(join(root, 'private.txt'), 'secret data');

    const toolsOmitted = createAgentTools({ root });
    const toolsEmpty = createAgentTools({ root, readablePaths: [] });

    const listFiles = (t) => JSON.parse(t.execute({ action: 'list_files', args: { path: '.' } }));
    const search = (t, query) => JSON.parse(t.execute({ action: 'search', args: { path: '.', query } }));
    const read = (t, path) => JSON.parse(t.execute({ action: 'read', args: { path } }));

    const l1 = listFiles(toolsOmitted);
    const l2 = listFiles(toolsEmpty);
    assert.deepStrictEqual(l1.files.sort(), ['private.txt', 'public.txt']);
    assert.deepStrictEqual(l1, l2, 'Omitted and empty readablePaths list files equally');

    const s1 = search(toolsOmitted, 'data');
    const s2 = search(toolsEmpty, 'data');
    assert.strictEqual(s1.hits[0].path, 'private.txt');
    assert.deepStrictEqual(s1, s2, 'Omitted and empty readablePaths search hits equally');

    const r1 = read(toolsOmitted, 'private.txt');
    const r2 = read(toolsEmpty, 'private.txt');
    assert.strictEqual(r1.text.trim(), 'secret data');
    assert.deepStrictEqual(r1, r2, 'Omitted and empty readablePaths read bytes equally');
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});"
  },
  "rationale": "The oracle tests that an omitted readablePaths configuration and an explicit empty array configuration both default to unrestricted access, satisfying the requirement that no behavior difference exists between these two states for file listing, searching, or direct reads."
}

